//! `agent` (src/models/agent/) against the database: scoping, ordering, paging.
//! Generated by `cargo offrails generate resource agents name:string description:text`.

use board::error::AppError;
use board::models::{Page, agent};

use crate::factories;
use crate::support::TestApp;

#[tokio::test]
async fn find_for_sees_only_the_owners_agents() {
    let app = TestApp::new().await;
    let alice = factories::user(app.db(), "alice@example.com").await;
    let bob = factories::user(app.db(), "bob@example.com").await;
    let record = factories::agent(app.db(), &alice).await;
    assert_eq!(
        agent::find_for(app.db(), &alice, record.id).await.unwrap(),
        record
    );
    assert!(matches!(
        agent::find_for(app.db(), &bob, record.id).await,
        Err(AppError::NotFound)
    ));
    assert!(matches!(
        agent::destroy_for(app.db(), &bob, record.clone()).await,
        Err(AppError::NotFound)
    ));
    assert!(factories::reload_agent(app.db(), record.id).await.is_some());
}

#[tokio::test]
async fn all_for_pages_newest_first() {
    let app = TestApp::new().await;
    let alice = factories::user(app.db(), "alice@example.com").await;
    let bob = factories::user(app.db(), "bob@example.com").await;
    let first = factories::agent(app.db(), &alice).await;
    let second = factories::agent(app.db(), &alice).await;
    let third = factories::agent(app.db(), &alice).await;
    factories::agent(app.db(), &bob).await;
    let (rows, more) = agent::all_for(app.db(), &alice, Page::new(1, 2))
        .await
        .unwrap();
    assert_eq!(rows, vec![third, second]);
    assert!(more);
    let (rows, more) = agent::all_for(app.db(), &alice, Page::new(2, 2))
        .await
        .unwrap();
    assert_eq!(rows, vec![first]);
    assert!(!more);
}

#[tokio::test]
async fn update_for_and_destroy_for_change_the_owners_agent() {
    let app = TestApp::new().await;
    let alice = factories::user(app.db(), "alice@example.com").await;
    let record = factories::agent(app.db(), &alice).await;
    let params = factories::agent_params(app.db(), &alice).await;
    let new = params.validate().unwrap();
    let updated = agent::update_for(app.db(), &alice, record.clone(), new)
        .await
        .unwrap();
    assert_eq!(updated.id, record.id);
    assert!(updated.updated_at >= record.updated_at);
    agent::destroy_for(app.db(), &alice, updated).await.unwrap();
    assert!(factories::reload_agent(app.db(), record.id).await.is_none());
}

/// The edit form shows what was saved: params from a record validate back to it.
#[tokio::test]
async fn the_edit_form_round_trips_a_saved_agent() {
    let app = TestApp::new().await;
    let alice = factories::user(app.db(), "alice@example.com").await;
    let record = factories::agent(app.db(), &alice).await;
    let new = agent::AgentParams::from(&record).validate().unwrap();
    let saved = agent::update_for(app.db(), &alice, record.clone(), new)
        .await
        .unwrap();
    assert_eq!(
        agent::Model {
            updated_at: record.updated_at,
            ..saved
        },
        record
    );
}
